#!/bin/bash
#
# Writes the configuration of logrotate for the logs that the containers
# leave on the Docker host. logrotate runs on the host, as root, so the
# file is installed by hand:
#
#   sudo install -m 644 -o root -g root logrotate/koitohan /etc/logrotate.d/koitohan

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(dirname "${SCRIPT_DIR}")"

source "${ROOT_DIR}/.env"

# tests/smoke.sh keeps its own generated files apart
GENERATED_ROOT="${KOITOHAN_GENERATED_ROOT:-${ROOT_DIR}}"

OUT_DIR="${GENERATED_ROOT}/logrotate"
LOGROTATE_CONF="${OUT_DIR}/koitohan"

# three years of daily files
KEEP_DAYS=1096
# debug.log takes every message of every device a second time
KEEP_DAYS_DEBUG=7

# the users the containers write as: PUID and PGID of syslog-ng in
# compose.yaml, and freerad of the FreeRADIUS image
SYSLOG_OWNER='1000 1000'
FREERADIUS_OWNER='101 101'

SYSLOG_LOG_DIR="${ROOT_DIR}/syslog-ng/log"
FREERADIUS_LOG_DIR="${ROOT_DIR}/freeradius/log"

if [ -z "${SYSLOG_CONTAINER_NAME}" ]; then
  echo "SYSLOG_CONTAINER_NAME is not set in .env." >&2
  exit 1
fi

REOPEN="docker exec ${SYSLOG_CONTAINER_NAME} syslog-ng-ctl reopen --control=/config/syslog-ng.ctl > /dev/null"

mkdir -p "${OUT_DIR}"

cat <<EOF > "${LOGROTATE_CONF}"
# Generated by scripts/generate_logrotate.sh. Do not edit.
#
# The rotated files carry the date of the day they cover (dateyesterday:
# logrotate runs shortly after midnight). The file of the day before
# stays uncompressed for one more day (delaycompress).

# The logs of the devices. syslog-ng keeps its files open, so it is told
# to reopen them, and makes the new files itself.
"${SYSLOG_LOG_DIR}/Hosts/*/*.log" {
    su ${SYSLOG_OWNER}
    daily
    dateext
    dateyesterday
    dateformat -%Y-%m-%d
    rotate ${KEEP_DAYS}
    compress
    delaycompress
    missingok
    notifempty
    nocreate
    sharedscripts
    postrotate
        ${REOPEN}
    endscript
}

# Every raw message of every device, kept for a short time.
"${SYSLOG_LOG_DIR}/debug.log" {
    su ${SYSLOG_OWNER}
    daily
    dateext
    dateyesterday
    dateformat -%Y-%m-%d
    rotate ${KEEP_DAYS_DEBUG}
    compress
    delaycompress
    missingok
    notifempty
    nocreate
    postrotate
        ${REOPEN}
    endscript
}

# The log of the FreeRADIUS server. FreeRADIUS keeps the file open, in
# append mode, so the file is copied and emptied in place, as the
# logrotate file that comes with the image does.
"${FREERADIUS_LOG_DIR}/radius.log" {
    su ${FREERADIUS_OWNER}
    daily
    dateext
    dateyesterday
    dateformat -%Y-%m-%d
    rotate ${KEEP_DAYS}
    compress
    delaycompress
    missingok
    notifempty
    copytruncate
}

# The requests and the replies, one file for each client
# (freeradius/config/mods-available/detail.log). FreeRADIUS makes a new
# file when the old one has been moved away.
"${FREERADIUS_LOG_DIR}/radacct/*/auth-detail" "${FREERADIUS_LOG_DIR}/radacct/*/reply-detail" {
    su ${FREERADIUS_OWNER}
    daily
    dateext
    dateyesterday
    dateformat -%Y-%m-%d
    rotate ${KEEP_DAYS}
    compress
    delaycompress
    missingok
    notifempty
    nocreate
}
EOF
